import 'package:flutter/material.dart';
import 'package:aupp/dinzo/dinzo-taxes.dart';
import 'package:aupp/investments/b3-catalog.dart';
import 'package:aupp/investments/investments-analytics.dart';
import 'package:aupp/investments/sec-data.dart';
import 'package:aupp/investments/us-catalog.dart';
import 'package:aupp/services/crypto-quote-service.dart';

/// A B3 company or fund, as shown for a stock position. Dinzo only sends the
/// ticker ("PETR4"), so the name and logo come from [b3Catalog] (generated by
/// scripts/b3_catalog.py), matched by the ticker root: PETR3 and PETR4 are
/// both Petrobras.
class StockCompany {
  /// Null when the catalogue has no readable name (some funds).
  final String? name;

  /// Asset path of the logo, or null for the ticker's initial.
  final String? logo;

  const StockCompany(this.name, this.logo);

  static final _ticker = RegExp(r'^([A-Z0-9]{4}\d{1,2})[A-Z]?$');

  /// B3 ticker of a stock, ETF or FII position ("PETR4"), or null.
  static String? tickerOf(DinzoInvestment inv) {
    final code = (inv.code ?? '').trim();
    // A letter at the end is not the stock itself: PETR4M is another instrument,
    // with another price and no company name.
    return _ticker.firstMatch(code)?.group(1);
  }

  /// "Petrobras · PETR4", or just the ticker when the name is unknown.
  static String titleOf(String ticker) {
    final name = of(ticker)?.name;
    return name == null ? ticker : '$name · $ticker';
  }

  /// The company's logo (or the ticker's initial) for [InstitutionLogo].
  static Institution badgeOf(String ticker) {
    final coin = cryptoLogoOf(ticker);
    if (coin != null) return Institution(ticker, coin, Colors.blueGrey);
    final company = of(ticker);
    return Institution(company?.name ?? ticker, company?.logo, Colors.blueGrey);
  }

  /// "PETR4" → Petrobras, "NVDA" → NVIDIA (abroad, [usCatalog]); null for a
  /// ticker not in the catalogues.
  static StockCompany? of(String? ticker) {
    final code = (ticker ?? '').trim().toUpperCase();
    if (usCatalog[code] case (final name, final file)) {
      return StockCompany(
        name,
        file == null ? null : 'assets/images/stocks_us/$file.png',
      );
    }
    final abroad = SecCatalog.instance.nameOf(code);
    if (code.length < 5 || code.contains('.')) {
      return abroad == null ? null : StockCompany(abroad, null);
    }
    final (name, file) = b3Catalog[code.substring(0, 4)] ?? (null, null);
    if (name == null && file == null) {
      return abroad == null ? null : StockCompany(abroad, null);
    }
    return StockCompany(
      name,
      file == null ? null : 'assets/images/stocks/$file.png',
    );
  }
}
